"""XR01: numerical and image-space witnesses, not perceptual/GPU validation.""" import cmath import math
def close(a, b, tolerance=1e-10): assert abs(a-b) <= tolerance, (a,b)
def decode_srgb(c): if not 0 <= c <= 1: raise ValueError("laboratory uses normalized nonnegative sRGB") return c/12.92 if c <= 0.04045 else ((c+0.055)/1.055)**2.4
def encode_srgb(c): if not 0 <= c <= 1: raise ValueError("laboratory uses normalized nonnegative linear RGB") return 12.92*c if c <= 0.0031308 else 1.055*c**(1/2.4)-0.055
def dft(values): n=len(values) return [sum(v*cmath.exp(-2j*math.pi*k*i/n) for i,v in enumerate(values)) for k in range(n)]
def ray(x,y,width,height,hfov_degrees): # Pixel centers; pinhole camera with square pixel pitch on its image plane. scale=math.tan(math.radians(hfov_degrees)/2) rx=(2*(x+0.5)/width-1)*scale ry=(1-2*(y+0.5)/height)*scale*height/width length=math.sqrt(rx*rx+ry*ry+1) return (rx/length,ry/length,1/length)
def angle(a,b): # Inputs are unit directions in a common frame. return math.degrees(math.acos(max(-1,min(1,sum(x*y for x,y in zip(a,b))))))
def blur(image): # Normalized 3x3 separable kernel, explicit clamped boundary policy. height,width=len(image),len(image[0]) taps=(0.25,0.5,0.25) return [[sum(taps[dy+1]*taps[dx+1] * image[min(height-1,max(0,y+dy))][min(width-1,max(0,x+dx))] for dy in (-1,0,1) for dx in (-1,0,1)) for x in range(width)] for y in range(height)]
def allocate_quality(image, gaze_ray, radius=5): # Full reference was computed first: this does NOT avoid original shading. height,width=len(image),len(image[0]) low=blur(image) output=[] for y in range(height): row=[] for x in range(width): e=angle(ray(x,y,width,height,60),gaze_ray) t=max(0,min(1,(e-radius)/5)) blend=t*t*(3-2*t) row.append((1-blend)*image[y][x]+blend*low[y][x]) output.append(row) return output
def metrics(reference, output, gaze_ray, sigma=5, floor=0.05): # Scalar linear-light toy data; same true gaze used for all comparisons. if sigma <= 0 or floor < 0: raise ValueError("invalid metric weights") height,width=len(reference),len(reference[0]) squares=[] weighted=total_weight=0.0 for y in range(height): for x in range(width): error=(reference[y][x]-output[y][x])**2 e=angle(ray(x,y,width,height,60),gaze_ray) weight=floor+math.exp(-e*e/(2*sigma*sigma)) squares.append(error) weighted+=weight*error total_weight+=weight mse=sum(squares)/len(squares) return mse,weighted/total_weight
def main(): width,distance,pixels=0.53,0.60,1920 fov=math.degrees(2*math.atan(width/(2*distance))) average_ppd=pixels/fov center_ppd=distance/(width/pixels)*math.pi/180 assert center_ppd < average_ppd print(f"planar FOV={fov:.6f} deg; average PPD={average_ppd:.6f}; " f"center PPD={center_ppd:.6f}")
for n in range(30): close(math.cos(2*math.pi*13*n/10),math.cos(2*math.pi*3*n/10)) close(math.sin(math.pi*n),0) checker=[float(i%2) for i in range(16)] wrong=checker[::2] prefiltered=[(checker[i]+checker[i+1])/2 for i in range(0,16,2)] assert all(v==0 for v in wrong) and all(v==0.5 for v in prefiltered)
n=128 values=[0.5+0.3*math.sin(2*math.pi*7*i/n)+ 0.1*math.sin(2*math.pi*29*i/n) for i in range(n)] spectrum=dft(values) close(spectrum[0].real/n,0.5) close(2*abs(spectrum[7])/n,0.3) close(2*abs(spectrum[29])/n,0.1) print("DFT interior one-sided amplitudes: bin7=0.3, bin29=0.1") for f in (0.05,0.25): print(f"Gaussian MTF at {f} cycles/pixel: " f"{math.exp(-2*math.pi**2*f*f):.6f}") close(decode_srgb(encode_srgb(0.5)),0.5,tolerance=1e-9) print(f"linear black/white mean encoded={encode_srgb(0.5):.6f}; " f"encoded 0.5 decodes={decode_srgb(0.5):.6f}")
scale,shape=2.0,3.0 threshold=scale*math.log(2)**(1/shape) close(1-0.5*math.exp(-(threshold/scale)**shape),0.75) alpha=0.2 squared_weight_sum=sum((alpha*(1-alpha)**j)**2 for j in range(1000)) close(squared_weight_sum,alpha/(2-alpha)) close(0.6+0.4*0.3,0.72)
w,h=32,24 image=[[0.5+0.25*math.sin(2*math.pi*7*x/w)+ 0.15*math.sin(2*math.pi*5*y/h) for x in range(w)] for y in range(h)] gaze=ray(23,12,w,h,60) fixed=allocate_quality(image,ray(15.5,11.5,w,h,60)) dynamic=allocate_quality(image,gaze) for label,output in (("fixed",fixed),("gaze-following",dynamic)): assert all(math.isfinite(v) for row in output for v in row) mse,weighted=metrics(image,output,gaze) print(f"{label}: MSE={mse:.8f}; weighted MSE={weighted:.8f}") flat=[[0.4]*w for _ in range(h)] close(metrics(flat,allocate_quality(flat,gaze),gaze)[0],0) print("XR01 numerical laboratory: all assertions passed")
if __name__ == "__main__": main()
